1	package retention
2	
3	import (
4		"fmt"
5	)
6	
7	// validateBatchInputs 校验一批销毁/核对请求共有的输入：
8	// 申请编号、处理日期、非空且去空白后无重复的档案名单。
9	// 返回去首尾空白后的申请编号、按提交顺序规范化的名单及名单集合。
10	// 任一输入无效即返回错误，调用方不得据此产生部分结果。
11	func validateBatchInputs(applicationID string, processedOn Date, rawIDs []string) (string, []string, map[string]struct{}, error) {
12		appID, err := requireText(applicationID, "申请编号")
13		if err != nil {
14			return "", nil, nil, err
15		}
16		if err := requireDate(processedOn, "处理日期"); err != nil {
17			return "", nil, nil, err
18		}
19		if len(rawIDs) == 0 {
20			return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单为空: %w",
21				appID, ErrEmptyDestructionList)
22		}
23	
24		// 规范化名单并检查名单内重复（输入校验先于任何业务判断）。
25		// 同一编号仅因首尾空白不同也视为重复。
26		ids := make([]string, 0, len(rawIDs))
27		for _, raw := range rawIDs {
28			id, err := requireText(raw, "档案编号")
29			if err != nil {
30				return "", nil, nil, err
31			}
32			ids = append(ids, id)
33		}
34		seen := make(map[string]struct{}, len(ids))
35		for _, id := range ids {
36			if _, dup := seen[id]; dup {
37				return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单中档案 %s 重复: %w",
38					appID, id, ErrDuplicateSelection)
39			}
40			seen[id] = struct{}{}
41		}
42		return appID, ids, seen, nil
43	}
44	
45	// Check 在正式办理销毁前做一次只读核对。
46	//
47	// 调用者提交申请编号、处理日期和档案编号名单，得到整批申请能否办理的报告，
48	// 一次看清所有阻碍。核对不销毁档案、不生成或改写清册，也不占用申请编号；
49	// 核对后（无论报告结论如何，甚至读取本地记录失败）仍可沿用同一编号继续
50	// 核对或正式提交。
51	//
52	// 报告区分四种结论：
53	//   - CheckReady 可以办理：申请编号尚未成功使用，名单中每份档案均无阻碍；
54	//   - CheckBlocked 存在阻碍：申请编号尚未成功使用，至少一份档案存在阻碍，
55	//     Results 按提交顺序列出每份档案的核对结果和全部适用阻碍；
56	//   - CheckReplayable 可以取回原清册：申请编号已成功使用，且日期与档案集合
57	//     （顺序无关）与原申请相同，Manifest 返回原清册，不因档案已销毁而判受阻；
58	//   - CheckConflict 申请编号冲突：沿用该编号但改变了日期或集合，Manifest 附原清册。
59	//
60	// 到期与冻结判断与 Destroy 完全一致：处理日期达到截止日当天即到期，
61	// 任一未解除冻结都会阻止销毁，已解除记录不作为阻碍。
62	//
63	// 申请编号或任一档案编号为空白、日期缺失或不是真实的 YYYY-MM-DD、
64	// 名单为空或含重复编号时，整次核对明确失败，不返回部分报告；
65	// 读取本地记录失败同样明确失败，绝不会用旧报告充当本次结果。
66	//
67	// 报告中的档案结果与清册来自同一次已保存状态读取；报告只说明核对当时的
68	// 情况，之后状态若变化，正式提交仍按最新状态判断。返回值是复制生成的
69	// 只读视图，调用者修改报告或其中清册不影响已保存的历史。
70	func (s *Store) Check(req CheckRequest) (CheckReport, error) {
71		appID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
72		if err != nil {
73			return CheckReport{}, err
74		}
75	
76		var report CheckReport
77		err = s.view(func(data *storeData) error {
78			report = CheckReport{
79				ApplicationID: appID,
80				ProcessedOn:   req.ProcessedOn,
81				Results:       make([]ArchiveCheckResult, 0, len(ids)),
82			}
83	
84			// 申请编号已成功使用：只判断能否取回原清册或编号冲突，两者都附原清册。
85			// 原清册取自当前这一次状态读取，与下面逐份核对看到的记录同源。
86			if existing, ok := data.Manifests[appID]; ok {
87				m := manifestFromRecord(existing)
88				report.Manifest = &m
89				if sameApplication(existing, req.ProcessedOn, seen) {
90					report.Status = CheckReplayable
91				} else {
92					report.Status = CheckConflict
93				}
94				return nil
95			}
96	
97			// 申请编号尚未成功使用：按提交顺序逐份核对，每份列出全部适用阻碍。
98			anyBlocked := false
99			for _, id := range ids {
100				r := ArchiveCheckResult{ID: id, Obstructions: []CheckObstruction{}}
101				ar, ok := data.Archives[id]
102				if !ok {
103					// 不存在的编号单独标明，不中断其他档案的核对。
104					r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionMissing})
105					anyBlocked = true
106					report.Results = append(report.Results, r)
107					continue
108				}
109				r.Exists = true
110				r.Category = ar.Category
111				r.Start = ar.Start
112				r.End = ar.End
113				r.Destroyed = ar.Destroyed
114	
115				if ar.Destroyed {
116					// 已销毁档案给出所属清册的申请编号和处理日期。
117					obs := CheckObstruction{Kind: ObstructionDestroyed}
118					if rec, ok := data.Manifests[ar.ManifestID]; ok {
119						obs.ManifestApplicationID = rec.ApplicationID
120						obs.ProcessedOn = rec.ProcessedOn
121					} else {
122						obs.ManifestApplicationID = ar.ManifestID
123					}
124					r.Obstructions = append(r.Obstructions, obs)
125					anyBlocked = true
126				} else {
127					// 未到期与未解除冻结可能同时成立，两类问题都要列出。
