package retention

import (
	"fmt"
	"sort"
	"strings"
)

// RegisterInput 是登记一份档案所需的信息。
//
// 编号和类别不能是空白；日期必须是 ParseDate 能解析的真实日期；
// 截止日可以与起算日相同，但不能更早。
type RegisterInput struct {
	ID       string
	Category string
	Start    Date
